// Configuration
const rss_feeds = [
  "https://hnrss.org/frontpage",
  "https://www.nasa.gov/rss/dyn/breaking_news.rss"
];

const topics = [
  "ai safety",
  "model context protocol",
  "n8n automation",
  "vector databases",
  "prompt injection"
];

const config = {
  cache_ttl_minutes: 45,
  dedupe_ttl_days: 10,
  min_score: 5,
  max_items_total: 30,
  enable_llm_summary: true,
  ZAI_API_KEY: $env.ZAI_API_KEY || "",
  ZAI_BASE_URL: $env.ZAI_BASE_URL || "https://api.z.ai/api/paas/v4",
  ZAI_MODEL: $env.ZAI_MODEL || "glm-5"
};

return [{ json: { rss_feeds, topics, config } }];

const items = $input.all();
const results = [];
const feedUrl = items[0].json.rss_url;

const sourceMap = {
  "hnrss.org": "hackernews",
  "nasa.gov": "nasa"
};

let source = "rss";
for (const [key, val] of Object.entries(sourceMap)) {
  if (feedUrl.includes(key)) source = val;
}

for (const item of items) {
  const data = item.json;
  results.push({
    json: {
      source: source,
      topic: null,
      title: data.title || "Untitled",
      url: data.link || data.guid || "",
      published_at: data.pubDate || data.isoDate || new Date().toISOString(),
      raw_score: 0,
      score: 5,
      summary_raw: data.contentSnippet || data.description || "",
      summary: null,
      meta: {
        author: data.creator || data.author || null,
        venue: source,
        cached: false
      }
    }
  });
}

return results;

const topic = $json.topic;
const config = $('Init').first().json.config;
const st = $getWorkflowStaticData('global');

if (!st.cache) st.cache = {};

const now = Date.now();
const ttl_ms = config.cache_ttl_minutes * 60 * 1000;

// Prune expired
for (const k in st.cache) {
  if (now - st.cache[k].ts_epoch_ms > ttl_ms) {
    delete st.cache[k];
  }
}

const cached = st.cache[topic];
if (cached && (now - cached.ts_epoch_ms < ttl_ms)) {
  return [{ json: { topic, config, cache_hit: true, cached_items: cached.items } }];
}

return [{ json: { topic, config, cache_hit: false } }];

const data = $json;
const topic = $('Cache Gate').first().json.topic;
const items = [];

if (data.items && Array.isArray(data.items)) {
  for (const i of data.items) {
    items.push({
      json: {
        source: "stackoverflow",
        topic: topic,
        title: i.title,
        url: i.link,
        published_at: new Date(i.creation_date * 1000).toISOString(),
        raw_score: i.score || 0,
        score: (i.score || 0) + (i.answer_count || 0),
        summary_raw: i.excerpt || "",
        summary: null,
        meta: { author: i.owner.display_name, venue: "StackOverflow", cached: false }
      }
    });
  }
}
return items;

const data = $json;
const topic = $('Cache Gate').first().json.topic;
const items = [];

if (data.message && data.message.items) {
  for (const i of data.message.items) {
    const title = (Array.isArray(i.title) ? i.title[0] : i.title) || "Untitled";
    const url = (i.URL && i.URL.startsWith('http')) ? i.URL : `https://doi.org/${i.DOI}`;
    const refs = i['is-referenced-by-count'] || 0;
    items.push({
      json: {
        source: "crossref",
        topic: topic,
        title: title,
        url: url,
        published_at: i.published ? i.published['date-parts'][0].join('-') : null,
        raw_score: refs,
        score: 20 + refs,
        summary_raw: i.abstract || "",
        summary: null,
        meta: { author: null, venue: i['container-title'] ? i['container-title'][0] : "Journal", cached: false }
      }
    });
  }
}
return items;

const items = $input.all().map(i => i.json);
const topic = $('Cache Gate').first().json.topic;
const st = $getWorkflowStaticData('global');

st.cache[topic] = {
  ts_epoch_ms: Date.now(),
  items: items
};

return items.map(i => ({ json: i }));

const config = $('Init').first().json.config;
const st = $getWorkflowStaticData('global');
if (!st.seen) st.seen = {};

const now = Date.now();
const dedupe_ms = config.dedupe_ttl_days * 24 * 60 * 60 * 1000;

// Prune seen
for (const k in st.seen) {
  if (now - st.seen[k] > dedupe_ms) delete st.seen[k];
}

const allItems = $input.all().map(i => i.json);
const stats = {
  candidates_total: allItems.length,
  new_items: 0,
  cached_hits: 0,
  api_calls: 0,
  failed_calls: 0,
  by_source: {}
};

const final = [];
for (const i of allItems) {
  stats.by_source[i.source] = (stats.by_source[i.source] || 0) + 1;
  if (i.meta.cached) stats.cached_hits++;

  if (i.url && !st.seen[i.url]) {
    if (i.score >= config.min_score) {
      final.push(i);
      st.seen[i.url] = now;
      stats.new_items++;
    }
  }
}

final.sort((a, b) => b.score - a.score);
const sliced = final.slice(0, config.max_items_total);

return [{ json: {
  config,
  stats,
  items: sliced,
  run_id: $workflow.id,
  generated_at: new Date().toISOString(),
  topics: $('Init').first().json.topics
} }];

const data = $json;
const topItems = data.items.slice(0, 12);
const content = topItems.map(i => `URL: ${i.url}\nTitle: ${i.title}\nRaw: ${i.summary_raw || ''}`).join('\n\n');

return [{
  json: {
    ...data,
    llm_payload: {
      model: data.config.ZAI_MODEL,
      messages: [{
        role: "user",
        content: `Summarize the following items into a JSON object with key 'summaries', an array of objects with 'url' and 'summary' (max 20 words).\n\n${content}`
      }],
      temperature: 0.3
    }
  }
}];

const original = $('Prepare LLM').first().json;
let summariesMap = {};

try {
  const content = $json.choices?.[0]?.message?.content;
  if (content) {
    const parsed = JSON.parse(content);
    if (Array.isArray(parsed.summaries)) {
      for (const s of parsed.summaries) {
        summariesMap[s.url] = s.summary;
      }
    }
  }
} catch (e) { console.error('LLM Parse Fail', e); }

const items = original.items.map(i => ({
  json: {
    ...i,
    summary: summariesMap[i.url] || i.summary_raw || i.title
  }
}));

return [{ json: { ...original, items } }];

const data = $json;
const items = data.items.map(i => ({
  json: {
    ...i,
    summary: i.summary_raw || i.title
  }
}));
return [{ json: { ...data, items } }];

const data = $json;
if (!Array.isArray(data.items)) throw new Error('Invalid items');
for (const i of data.items) {
  if (!i.url || typeof i.score !== 'number') throw new Error('Invalid item fields');
  if (JSON.stringify(i).includes('{{')) throw new Error('Mustache detected');
}
return [{ json: data }];

const data = $json;
const groups = {};
for (const i of data.items) {
  if (!groups[i.source]) groups[i.source] = [];
  groups[i.source].push(i);
}

let md = `# PulseMosaic Digest - ${data.generated_at}\n\n`;
for (const [src, items] of Object.entries(groups)) {
  md += `## ${src.toUpperCase()}\n`;
  for (const i of items) {
    md += `- [${i.title}](${i.url}) (Score: ${i.score})\n`;
    if (i.summary) md += `  > ${i.summary}\n`;
  }
  md += `\n`;
}

return [{ json: { ...data, digest_markdown: md } }];
